def _local_pid_is_alive(pid: int | None) -> bool:
    """Best-effort liveness probe for same-host lease reclaim after hard kills."""
    if pid is None or int(pid) <= 0:
        return False
    try:
        os.kill(int(pid), 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except OSError:
        return False
    return True

